							let data = "";
							req.on("data", (chunk) => {
								data += chunk;
							});
							req.on("end", () => {
								try {
									resolve(JSON.parse(data || "{}"));
								} catch {
									resolve(null);
								}
							});
							req.on("error", () => resolve(null));
